/* Generated by meson on a normal build; this CMake wrapper stands in for it,
 * with the value coming from Kconfig.
 *
 * manager.hpp and main.cpp include "config.h", and the CMake build has no
 * configure_file step to produce it. Without this file the include would
 * resolve to another module's config.h -- several exist in the tree.
 */
#pragma once

#include "types.hpp"

/* NTP is the built-in default only when the client is compiled in. Without
 * it the firmware can do nothing but manual time setting, so claiming NTP
 * would leave manager.cpp and timedated disagreeing about the mode. */
#if defined(CONFIG_OPENBMC_PHOSPHOR_TIME_MANAGER_NTP)
#define DEFAULT_TIME_MODE Mode::NTP
#else
#define DEFAULT_TIME_MODE Mode::Manual
#endif